/// A file `fkit` copies into a project.
///
/// Once written it belongs to the project: nothing tracks or
/// updates it afterwards.
class Template {
  const Template({
    required this.name,
    required this.description,
    required this.kits,
    required this.pub,
    required this.output,
    required this.body,
  });

  /// Kebab-case identifier passed on the command line.
  final String name;

  /// One line, shown by the matching `ls` command.
  final String description;

  /// Kits it imports; `create` checks they are installed.
  final List<String> kits;

  /// pub.dev packages it imports directly. A kit depending on one
  /// is not enough — your own code needs its own entry.
  final List<String> pub;

  /// Default destination, relative to the project root.
  final String output;

  /// The file contents.
  final String body;
}

